local function __load(name, files, saved)
  local ns = {}
  for _, f in ipairs(files) do
    local chunk, err = loadfile(f)
    if not chunk then error(err, 0) end
    stub.addonSources["@" .. f] = name
    chunk(name, ns)
  end
  if saved then saved() end
  stub.addonLoaded(name)
  return ns
end
